import{_ as t,o as s,c as o,a2 as a}from"./chunks/framework.BI-oZTPy.js";const u=JSON.parse('{"title":"Save sync","description":"","frontmatter":{},"headers":[],"relativePath":"saves.md","filePath":"saves.md"}'),r={name:"saves.md"};function n(i,e,d,h,l,g){return s(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="save-sync" tabindex="-1">Save sync <a class="header-anchor" href="#save-sync" aria-label="Permalink to &quot;Save sync&quot;">​</a></h1><p>Gameyfin backs up your saves after you play and restores the newest one before you start, on every PC that syncs to the same place. You can also restore older versions and move saves to a new location.</p><blockquote><p><strong>Using a Gameyfin server for saves</strong> needs server support that is not merged into <a href="https://github.com/gameyfin/gameyfin" target="_blank" rel="noreferrer">Gameyfin</a> yet. Until it is, run <code>ghcr.io/wieluk/gameyfin:gameyfin-app</code> as your server. A folder or WebDAV share works with any Gameyfin server.</p></blockquote><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ol><li><strong>Finding saves.</strong> Gameyfin uses <a href="https://github.com/mtkennerly/ludusavi" target="_blank" rel="noreferrer">Ludusavi</a>, which comes with the app. Ludusavi has a community database of where thousands of games keep their saves: files in Documents or AppData, folders beside the game, and on Windows, registry keys.</li><li><strong>Backing up.</strong> When a game closes, Ludusavi copies its save files into <code>Gameyfin/Saves</code> in your games folder. Gameyfin packs them and uploads them as a new version, but only if something changed.</li><li><strong>Restoring.</strong> Before a game starts, Gameyfin checks for a newer version from another PC, downloads it and lets Ludusavi put each file back where it belongs.</li></ol><p>A small window shows each step. You can skip a restore while it downloads. A session that started without the newer save is then not uploaded afterwards, so it cannot bury that save; you choose which one to keep under <strong>Saves</strong>. If a restore fails, the game waits for you instead of starting on an old save.</p><p>If the place your saves are kept cannot be reached, for example on a Steam Deck away from home, the game starts with the save on this PC. The upload after playing waits and is tried again every few minutes while Gameyfin runs, so the save reaches your other PCs once you are back online.</p><h3 id="recognising-a-game" tabindex="-1">Recognising a game <a class="header-anchor" href="#recognising-a-game" aria-label="Permalink to &quot;Recognising a game&quot;">​</a></h3><p>Gameyfin matches each game to the Ludusavi database by its Steam AppID if your server knows it, then by title. It never guesses: if it is not certain, the game shows <strong>Not sure which game this is</strong> and you press <strong>Choose game</strong> to pick the right entry. A wrong match would restore one game&#39;s save over another&#39;s.</p><p>You only do this on one PC. Every save carries the entry it was made under, so your other PCs use the same one.</p><p>The database updates itself once a day, and a game that was not recognised is looked up again after each update. To get a new game in sooner, press <strong>Update game database</strong> in <strong>Settings, Saves</strong>.</p><h2 id="where-saves-are-kept" tabindex="-1">Where saves are kept <a class="header-anchor" href="#where-saves-are-kept" aria-label="Permalink to &quot;Where saves are kept&quot;">​</a></h2><p><strong>Settings, Saves, Where saves are kept</strong>:</p><table tabindex="0"><thead><tr><th>Location</th><th>Use it when</th></tr></thead><tbody><tr><td><strong>Gameyfin server</strong></td><td>Your server supports save sync (see the note above). Retention is set on the server.</td></tr><tr><td><strong>A folder</strong></td><td>Something else syncs that folder: Syncthing, rclone, Nextcloud or Dropbox. In the Flatpak it must be inside your home folder. If two PCs upload before the folder has caught up, the next sync shows a <a href="#conflicts">conflict</a> rather than picking one.</td></tr><tr><td><strong>WebDAV</strong></td><td>You have a Nextcloud, ownCloud or other WebDAV share and do not want to mount it. Use an app password: it is stored unencrypted.</td></tr></tbody></table><p>For a folder or WebDAV, <strong>Versions to keep per game</strong> (default 10) sets how many old versions stay. Press <strong>Test connection</strong> after changing anything.</p><p>Other options:</p><ul><li><strong>Sync my saves</strong>: the main switch.</li><li><strong>Restore before a game starts</strong> and <strong>Back up after a game closes</strong>: the two automatic steps.</li><li><strong>This device&#39;s name</strong>, in <strong>Settings, Account</strong>: shown beside every save this PC uploads.</li></ul><h2 id="the-saves-page" tabindex="-1">The Saves page <a class="header-anchor" href="#the-saves-page" aria-label="Permalink to &quot;The Saves page&quot;">​</a></h2><p>Each game shows one line saying where it stands:</p><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th><th>What to do</th></tr></thead><tbody><tr><td>Backed up</td><td>This PC and the store match.</td><td>Nothing.</td></tr><tr><td>Played, not uploaded yet</td><td>You played since the last upload.</td><td>Nothing: it uploads by itself once it can. <strong>Back up</strong> does it now.</td></tr><tr><td>A newer save from another PC</td><td>Another PC uploaded since.</td><td><strong>Restore</strong>, or just start the game.</td></tr><tr><td>Both have unsaved progress</td><td>Both PCs played since they last synced.</td><td><strong>Resolve</strong>, see <a href="#conflicts">Conflicts</a>.</td></tr><tr><td>Only saved on (system), which does not restore onto (system) by itself</td><td>The only stored save comes from a system whose save folders differ from this PC&#39;s.</td><td><strong>Back up</strong> this PC&#39;s own save, or see <a href="#windows-proton-and-linux">Windows, Proton and Linux</a>.</td></tr><tr><td>Not sure which game this is</td><td>No certain database match.</td><td><strong>Choose game</strong>, or <strong>Set folders</strong>.</td></tr><tr><td>Nothing saved yet, or the saves are not where the game keeps them</td><td>Recognised, but no files found.</td><td>Play first, or <strong>Set folders</strong>.</td></tr><tr><td>Not backed up yet</td><td>Never synced on this PC.</td><td><strong>Back up</strong>.</td></tr><tr><td>An error in red</td><td>The last backup or restore failed, for the reason shown.</td><td>Fix the cause, then <strong>Try again</strong>.</td></tr></tbody></table><p><strong>Show</strong> picks the list: <strong>Installed</strong> (the default), <strong>With saves</strong> adds games with stored saves that are not installed here, and <strong>All games</strong> lists your whole library. A save can only be restored once its game is installed. <strong>Search saves</strong> narrows the list by title.</p><p>A line above the list counts what needs you, such as a newer save to restore or a failed backup, and those games come first.</p><p>Expand a game to:</p><ul><li>see every <strong>stored version</strong> with its date, device, system and size</li><li><strong>restore</strong> any version that works on this PC</li><li><strong>lock</strong> a version so cleanup never removes it</li><li><strong>delete</strong> versions</li><li><strong>Open folder</strong> where the saves are on this PC</li><li><strong>Set folders</strong> or <strong>Choose game</strong></li></ul><p>The <strong>⋯</strong> menu at the top holds the actions for every game at once, each asking first:</p><ul><li><strong>Back up all</strong>: backs up every installed game whose saves were found, one after another. An unchanged save is not uploaded again, and a game with a newer save elsewhere is left for you to decide.</li><li><strong>Open backups folder</strong>: opens <code>Gameyfin/Saves</code>.</li><li><strong>Delete all saves</strong>: removes every stored save for every game. Save files on this PC are not touched.</li></ul><h2 id="first-start-on-a-pc" tabindex="-1">First start on a PC <a class="header-anchor" href="#first-start-on-a-pc" aria-label="Permalink to &quot;First start on a PC&quot;">​</a></h2><p>The first time you start a game on a PC and saves for it already exist in the store, Gameyfin settles it by itself where it can:</p><ul><li><strong>No save files on this PC</strong>: the newest stored save is restored and the game starts.</li><li><strong>The same save already here</strong>, for example through Steam Cloud: it is taken as synced.</li></ul><p>Only when this PC has save files that differ from the stored ones does Gameyfin ask <strong>Which save?</strong>, since you may have played the game here before using Gameyfin. The dialog says when this PC&#39;s files last changed, so you can compare.</p><ul><li><strong>Restore and play</strong>: pick a version (the newest one that works here is preselected).</li><li><strong>Keep mine and play</strong>: keeps and uploads what this PC has. The stored save stays in the version history.</li><li><strong>Not now</strong>: the game does not start, and the question comes back next time.</li></ul><h2 id="conflicts" tabindex="-1">Conflicts <a class="header-anchor" href="#conflicts" aria-label="Permalink to &quot;Conflicts&quot;">​</a></h2><p>A conflict means two PCs both played since they last synced, so one save would overwrite the other. Gameyfin asks as soon as it finds one: before the game starts, so you never play on the wrong save, or after it closes. It shows both side by side:</p><ul><li><strong>Keep this PC&#39;s save</strong>: uploads it. The other stays in the version history.</li><li><strong>Keep the cloud save</strong>: restores the other PC&#39;s save over this one.</li><li><strong>Keep both</strong>: uploads this PC&#39;s save and locks the other, so cleanup never removes it. You can restore either later.</li><li><strong>Not now</strong> (or <strong>Decide later</strong>): before a game starts, it does not start.</li></ul><h2 id="windows-proton-and-linux" tabindex="-1">Windows, Proton and Linux <a class="header-anchor" href="#windows-proton-and-linux" aria-label="Permalink to &quot;Windows, Proton and Linux&quot;">​</a></h2><p>Saves carry the system they were made on:</p><table tabindex="0"><thead><tr><th>Tag</th><th>Made by</th></tr></thead><tbody><tr><td><strong>Windows</strong></td><td>a game on Windows</td></tr><tr><td><strong>Windows, on Proton</strong></td><td>a Windows game on Linux, through Proton or Wine</td></tr><tr><td><strong>Linux</strong></td><td>a native Linux build</td></tr></tbody></table><p><strong>Windows and Proton saves are interchangeable.</strong> A Windows game on Linux keeps its saves in Windows-style folders inside its prefix, and Gameyfin maps that prefix&#39;s user folder onto the real user folder on Windows. So you can play on a Windows desktop, carry on on a Steam Deck, and go back.</p><p>Your username and install folder do not matter either: both are stored as neutral placeholders and filled in with this PC&#39;s own paths on restore. The same goes for a Documents folder OneDrive has moved on Windows, and for folders a Wine prefix links into your Linux home.</p><p><strong>Windows or Proton to a native Linux build</strong> does not map on its own, because the save folders are completely different. Each system then keeps its own line of saves: a native Linux PC syncs with other native Linux PCs and ignores the Windows saves, and the other way round. Saves that do not work on this PC are greyed out in its version list.</p><p>To carry saves between them anyway, open <strong>Set folders</strong> on each PC:</p><ol><li>Under <strong>Different folders on other PCs</strong>, add the game&#39;s save folder on that PC and give it the same <strong>stored as</strong> name on every PC.</li><li>Turn on <strong>Use saves from other systems</strong>.</li></ol><p>Registry settings are not carried.</p><p><strong>Registry saves.</strong> A few games keep saves or settings in the Windows registry. On Windows, Ludusavi backs those up. Inside a Proton prefix only files are captured.</p><h2 id="steam" tabindex="-1">Steam <a class="header-anchor" href="#steam" aria-label="Permalink to &quot;Steam&quot;">​</a></h2><ul><li><strong>Games from Steam itself</strong> are not synced automatically, since only games in your Gameyfin library are. If the same game is in your library, <strong>Find saves on this PC</strong> (below) can back up the progress you made in Steam.</li><li><strong>Steam AppIDs</strong> from your server make recognition more reliable.</li><li><strong>A Gameyfin game added to Steam</strong> as a shortcut still starts through Gameyfin, so its saves sync as usual. See <a href="./playing#shortcuts">Shortcuts</a>.</li></ul><h2 id="find-saves-on-this-pc" tabindex="-1">Find saves on this PC <a class="header-anchor" href="#find-saves-on-this-pc" aria-label="Permalink to &quot;Find saves on this PC&quot;">​</a></h2><p><strong>Saves, Find saves on this PC</strong> scans the whole machine for anything the Ludusavi database recognises: normal save locations, your Steam library (including Proton games&#39; saves on Linux) and every Gameyfin prefix. It can take a few minutes.</p><p>Each find is matched to a game in your library where possible. Tick what you want and press <strong>Back up</strong>. A find with no match needs <strong>Match to a game</strong> first, since a stored save always belongs to a library game. Nothing is backed up until you tick it.</p><p>Use this when you start using Gameyfin on a PC that already has progress.</p><h2 id="set-folders" tabindex="-1">Set folders <a class="header-anchor" href="#set-folders" aria-label="Permalink to &quot;Set folders&quot;">​</a></h2><p>For a game the database does not know, or where it looks in the wrong place, press <strong>Set folders</strong> on its row.</p><ul><li><strong>Save folders</strong>: where this game keeps saves on this PC. Adding one lets an unknown game be backed up. For a known game, the folders are added to what the database already finds. The dialog shows where saves were already found, and offers folders named like the game in the usual save places: press <strong>Add</strong> on one. For a Windows game on Linux, <strong>Browse</strong> starts inside its prefix, and a folder picked there still lands in the right place on a Windows PC.</li><li><strong>Different folders on other PCs</strong>: only for a save kept in a different folder on another PC. Set the folder on each PC. Leave <strong>stored as</strong> blank and it is named after the game, so it matches on every PC.</li><li><strong>Use saves from other systems</strong>: restores saves made on Windows or Linux here too. Turn it on once the folders above are mapped on each PC.</li></ul><p>Save folders travel with the save: another PC that restores it uses the same folders, so you only set them once.</p><h2 id="move-saves" tabindex="-1">Move saves <a class="header-anchor" href="#move-saves" aria-label="Permalink to &quot;Move saves&quot;">​</a></h2><p><strong>Settings, Saves, Move saves</strong> copies saves between the server, a folder and WebDAV, for example when switching location.</p><ul><li>Nothing is deleted from the source, so running it again is safe and only copies what is missing.</li><li>By default only each game&#39;s newest save is copied. Tick <strong>Copy every version</strong> for the full history.</li><li>Both locations use their own settings, so set up the new one before copying.</li></ul><h2 id="ludusavi-version" tabindex="-1">Ludusavi version <a class="header-anchor" href="#ludusavi-version" aria-label="Permalink to &quot;Ludusavi version&quot;">​</a></h2><p>A copy of Ludusavi ships with the app. <strong>Settings, Saves</strong> can download a newer or an older version. Removing a downloaded one falls back to the built-in copy. Your backups are not affected either way.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Problem</th><th>Try</th></tr></thead><tbody><tr><td>&quot;Your server does not support save sync&quot;</td><td>The server lacks save support. Use <code>ghcr.io/wieluk/gameyfin:gameyfin-app</code>, or a folder or WebDAV.</td></tr><tr><td>&quot;Save sync is turned off on your server&quot;</td><td>An administrator switched it off on the server.</td></tr><tr><td>A game is not recognised</td><td><strong>Choose game</strong>, or <strong>Set folders</strong>. Your other PCs pick up the answer.</td></tr><tr><td>Backed up but nothing found</td><td>Play and save in the game first. Check <strong>Open folder</strong>, then <strong>Set folders</strong>.</td></tr><tr><td>Restored to the wrong place</td><td>Check <strong>Choose game</strong> picked the right entry. Fix paths with <strong>Set folders</strong>.</td></tr><tr><td>A save from Windows will not restore on a native Linux build</td><td>Map the folders under <strong>Set folders</strong> on both PCs, then turn on <strong>Use saves from other systems</strong>.</td></tr><tr><td>A save did not reach another PC</td><td>It uploads once the place your saves are kept can be reached again. <strong>Back up</strong> tries now.</td></tr></tbody></table>',61)])])}const p=t(r,[["render",n]]);export{u as __pageData,p as default};
